def bboxes(g,v):
    g=np.array(g); H,W=g.shape; seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if g[i,j]==v and (i,j) not in seen:
                s={(i,j)}; added=True
                while added:
                    added=False
                    for a,b in list(s):
