import collections

def solve(g, target_rare=None):
    H,W=len(g),len(g[0])
    # find rectangles whose border is uniform AND interior contains at least one pixel of another color
    cands=[]
    for i1 in range(H):
        for j1 in range(W):
            for h in range(2,H-i1+1):
                for w2 in range(2,W-j1+1):
                    c=g[i1][j1]
                    if not(all(g[i1+r][j1]==c for r in range(h))
                          and all(g[i1+h-1][j1+c2]==c for c2 in range(w2))
                          and all(g[i1+r][j1+w2-1]==c for r in range(h))
                          and all(g[i1][j1+c2]==c for c2 in range(w2))):
                        continue
                    inner=[g[r][cc2] for r in range(i1+1,i1+h-1) for cc2 in range(j1+1,j1+w2-1)]
                    if not set(inner): continue
                    if any(x!=c for x in inner):
                        cands.append((i1,j1,h,w2,c,set(inner)))
    # pick frame with exactly 2 distinct colors and 2-color interior pattern (demo style)
    best=None
    for i1,j1,h,w2,c,ins in cands:
        sub=[[g[i1+r][j1+cc2] for cc2 in range(j1,j1+w2)] for r in range(i1,i1+h)]
        ins_sorted=list(collections.Counter(ins).items())
        # candidate: border recolored to X where X is the least frequent of the OTHER colors in the full grid
        counts=collections.Counter(x for row in g for x in row)
        others=[k for k,v in counts.items() if k!=c]
        # choose the color among others appearing as "filler"/non-noise: in demo it's the least common of {others}
        X=min(others,key=lambda k:(counts[k],-k)) if others else None
        pred=[row[:] for row in sub]
        for r in [0,h-1]:
            for cc in range(w2): pred[r][cc]=X
        for cc in range(w2):
            for r in range(h): pred[r][cc]=X
        yield i1,j1,h,w2,pred,X,dic(counts)

