    best=None
    for oh in range(2,H+1):
        for ow in range(2,W+1):
            for i1 in range(H-oh+1):
                for j1 in range(W-ow+1):
                    ok=True
                    bc=None
                    for r in range(oh):
                        rowvals=set(inp[i1+r][j1] for c in range(j1,j1+ow))
                        if len(rowvals)>1: ok=False;break
                        if bc is None and all(inp[i1+r][c]==rowvals.pop() for c in range(j1,j1+ow)):
